//! TypeScript declarations emitted into the generated `.d.ts`.
//!
//! `ts/types.d.ts` is generated by `tools/bindings/gen_dts.py` from the
//! rustdoc JSON: one interface or union per serde type of `fontpixel` and
//! `fontpixel-ops`, with the number policy of [`crate::conv`]. `ts/aliases.d.ts`
//! holds the hand-written argument aliases (`BytesLike`, `ResourcesLike`, …).
//! Both land in the wasm-bindgen declaration file, so `unchecked_param_type`
//! and `unchecked_return_type` names resolve there; the custom sections cost
//! nothing at run time (wasm-bindgen strips them from the module).
use wasm_bindgen::prelude::*;

#[wasm_bindgen(typescript_custom_section)]
const ALIASES: &str = include_str!("../ts/aliases.d.ts");

#[wasm_bindgen(typescript_custom_section)]
const TYPES: &str = include_str!("../ts/types.d.ts");
